#include "cg_screen.hpp"
extern "C" {
#include "font.h"
}
#include <iostream>
int main(int argc,char**argv){KFont*font=nullptr;try{if(argc!=2)return 2;qlie::Assets assets(argv[1]);whj2::Progress progress;whj2::CgCatalog catalog(assets);font=kfont_open(nullptr,0);if(!font)throw std::runtime_error("Font");whj2::CgScreen screen(assets,progress,font);screen.open();screen.update(500);screen.confirm();if(screen.inView())throw std::runtime_error("Locked CG opened");
 screen.move(0,-1);screen.move(1,0);screen.confirm();screen.update(500);if(screen.pageIndex()!=1)throw std::runtime_error("CG second page");if(screen.tap(1210,695)!=whj2::CgScreen::Back)throw std::runtime_error("CG back button");
 whj2::SceneImages seen(assets);seen.command("^bg1,file:"+catalog.items()[0].files[0].substr(6));qlie::Bytes first(1280*720*4),next(first.size());seen.draw(first);progress.captureFiles(seen.takeShownFiles());screen.open();screen.update(500);screen.confirm();if(!screen.inView())throw std::runtime_error("Seen group locked");screen.draw(first);screen.confirm();screen.draw(next);if(screen.variantIndex()!=1||first==next)throw std::runtime_error("CG difference image missing");screen.move(-1,0);screen.toggleZoom();screen.pan(0,0);screen.draw(first);screen.pan(1280,720);screen.draw(next);if(first==next)throw std::runtime_error("CG zoom pan missing");screen.back();if(screen.zoomLevel()!=1||!screen.inView())throw std::runtime_error("Zoom cancel");screen.back();if(screen.inView()||screen.pageIndex()!=0)throw std::runtime_error("CG returns original page");
 unsigned animated=0;while(animated<catalog.items().size()&&catalog.items()[animated].files[0].substr(catalog.items()[animated].files[0].size()-2)!=".b")animated++;if(animated==catalog.items().size())throw std::runtime_error("Missing original animated CG group");seen.clear();seen.command("^bg1,file:"+catalog.items()[animated].files[0].substr(6));seen.draw(first);progress.captureFiles(seen.takeShownFiles());screen.open();screen.update(500);screen.move(0,-1);screen.move(1,0);screen.confirm();screen.update(500);unsigned position=animated%24;for(unsigned i=0;i<position;i++)screen.move(1,0);screen.confirm();if(!screen.inView())throw std::runtime_error("Animated group did not open");screen.update(100);screen.draw(first);screen.update(500);screen.draw(next);if(first==next)throw std::runtime_error("Animated CG did not update");
 kfont_close(font);std::cout<<"PASS CG locks/pages/PNG differences/zoom pan/cancel/original animation group="<<animated<<"\n";return 0;}catch(const std::exception&e){if(font)kfont_close(font);std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
